// spec: specs/contact-login-return.md (4.1–4.3) · кейсы: .qa/tests/contact-login-return/CONTACT-AUTH-12, -13, -14.md
// seed: tests/seed.spec.ts (гость) · прод, только чтение (запись заблокирована), вход не выполняется, «שלח קוד» не нажимается.
// Не проверяется (известное, принято пользователем): брошенный Google (b4s_oauth_started_at, 60 с),
// обновление на /auth?mode=sms, «назад» с /auth после «פרסם עסק».
import { test, expect } from '@playwright/test';
import {
  prepareGuest, openAuthFromPopup, expectPlainAuth, expectNoReturn, LISTING_ID, LOAD,
} from './contact-popup.helpers';

test.use({ serviceWorkers: 'block' });

test.describe('Отказ от входа — адрес возврата и намерение очищаются', () => {
  for (const device of ['@desktop', '@android']) {
    test(`«назад» с /auth → главная → обычный /auth без возврата и без «להתעניין בעסקים» #a88c1c ${device} @prod-safe`, async ({ page }) => {
      await prepareGuest(page);
      await openAuthFromPopup(page);

      await page.goBack();
      await page.waitForURL((u) => u.pathname === '/businessdetail' && u.searchParams.get('id') === LISTING_ID, LOAD);
      await expectNoReturn(page, 'после «назад» с /auth');

      await page.goto('/home');
      await page.waitForURL((u) => u.pathname === '/home', LOAD);

      await page.goto('/auth');
      await expectPlainAuth(page, 'обычный /auth после отказа');
    });

    test(`Уход с /auth на другой адрес (/search) → обычный /auth без возврата #a88c1c ${device} @prod-safe`, async ({ page }) => {
      await prepareGuest(page);
      await openAuthFromPopup(page);

      await page.goto('/search');
      await page.waitForURL((u) => u.pathname === '/search', LOAD);
      await expectNoReturn(page, 'после перехода на /search');

      await page.goto('/auth');
      await expectPlainAuth(page, 'обычный /auth после ухода на /search');
    });
  }

  test('После отказа: повторный /auth, обновление и ещё один /auth — обычный экран, возврат не появляется #a88c1c @android @prod-safe', async ({ page }) => {
    await prepareGuest(page);
    await openAuthFromPopup(page);

    await page.goBack();
    await page.waitForURL((u) => u.pathname === '/businessdetail', LOAD);

    await page.goto('/auth');
    await expectPlainAuth(page, 'первый /auth после отказа');

    await page.reload();
    await expectPlainAuth(page, '/auth после обновления');

    await page.goto('/home');
    await page.waitForURL((u) => u.pathname === '/home', LOAD);
    await page.goto('/auth');
    await expectPlainAuth(page, 'второй /auth после главной');
  });
});
